CORS(app)

UPLOAD_FOLDER = 'generated_images'
if not os.path.exists(UPLOAD_FOLDER):
    os.makedirs(UPLOAD_FOLDER)

API_KEY = os.environ.get('FLYMY_API_KEY', 'fly-')

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/api/generate', methods=['POST'])
def generate_image():
    try:
        data = request.json
        prompt = data.get('prompt', '')
        negative_prompt = data.get('negative_prompt', '')
        width = data.get('width', 1024)
        height = data.get('height', 1024)
        steps = data.get('steps', 30)
        guidance = data.get('guidance', 7.5)

        if not prompt:
            return jsonify({'error': 'Prompt is required'}), 400

        fma_client = client(apikey=API_KEY)

        payload = {
            'prompt': prompt,
            'negative_prompt': negative_prompt,
            'width': width,
            'height': height,
            'num_inference_steps': steps,
            'guidance_scale': guidance,
            'seed': int(datetime.now().timestamp())
        }

        response = fma_client.predict(
            model='flymyai/nano-banana-pro',
            payload=payload
        )

        if 'sample' in response.output_data:
            sample_encoded = response.output_data['sample'][0]
            sample = base64.b64decode(sample_encoded)

            filename = f"{uuid.uuid4()}.jpg"
            filepath = os.path.join(UPLOAD_FOLDER, filename)

