from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
from flymyai import client
import base64
import os
import uuid
from datetime import datetime
from werkzeug.utils import secure_filename
import requests
from io import BytesIO
from PIL import Image

app = Flask(__name__)
CORS(app)

UPLOAD_FOLDER = 'uploads'
GENERATED_FOLDER = 'generated'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'tiff'}

for folder in [UPLOAD_FOLDER, GENERATED_FOLDER]:
    if not os.path.exists(folder):
        os.makedirs(folder)

app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
app.config['GENERATED_FOLDER'] = GENERATED_FOLDER
app.config['MAX_CONTENT_LENGTH'] = 50 * 1024 * 1024

API_KEY = os.environ.get('FLYMY_API_KEY', 'fly-')

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/api/upload', methods=['POST'])
def upload_image():
    try:
        if 'file' not in request.files:
            return jsonify({'error': 'No file provided'}), 400

        file = request.files['file']

        if file.filename == '':
            return jsonify({'error': 'No file selected'}), 400

        if not allowed_file(file.filename):
            return jsonify({'error': 'Invalid file type'}), 400

        filename = secure_filename(f"{uuid.uuid4()}_{file.filename}")
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
        file.save(filepath)

        img = Image.open(filepath)
        width, height = img.size

        return jsonify({
            'success': True,
            'filename': filename,
            'path': f'/uploads/{filename}',
            'width': width,
            'height': height
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/generate', methods=['POST'])
def generate_image():
    try:
        data = request.json
        prompt = data.get('prompt', '')
        negative_prompt = data.get('negative_prompt', '')
        width = data.get('width', 4096)
        height = data.get('height', 4096)
        steps = data.get('steps', 50)
        guidance = data.get('guidance', 7.5)
        aspect_ratio = data.get('aspect_ratio', '1:1')
        resolution = data.get('resolution', '4K')
        num_images = data.get('num_images', 1)
        seed = data.get('seed', -1)
        source_image = data.get('source_image', None)

        if not prompt:
            return jsonify({'error': 'Prompt is required'}), 400

        fma_client = client(apikey=API_KEY)

        if seed == -1:
            seed = int(datetime.now().timestamp() * 1000000) % 2147483647

        payload = {
            'prompt': prompt,
            'negative_prompt': negative_prompt,
            'num_inference_steps': steps,
            'guidance_scale': guidance,
            'seed': seed,
            'num_images': num_images
        }

        if source_image:
            image_path = os.path.join(app.config['UPLOAD_FOLDER'], source_image)
            if os.path.exists(image_path):
                with open(image_path, 'rb') as img_file:
                    img_data = base64.b64encode(img_file.read()).decode('utf-8')
                    payload['image'] = img_data
                    payload['strength'] = data.get('strength', 0.75)

        payload['aspect_ratio'] = aspect_ratio
        payload['resolution'] = resolution
        payload['width'] = width
        payload['height'] = height

        response = fma_client.predict(
            model='flymyai/nano-banana-pro',
            payload=payload
        )

        generated_images = []

        if 'images' in response.output_data:
            for idx, img_data in enumerate(response.output_data['images']):
                if isinstance(img_data, str):
                    if img_data.startswith('http'):
                        img_response = requests.get(img_data)
                        img_bytes = img_response.content
                    else:
                        img_bytes = base64.b64decode(img_data)
                else:
                    img_bytes = img_data

                filename = f"{uuid.uuid4()}.png"
                filepath = os.path.join(app.config['GENERATED_FOLDER'], filename)

                with open(filepath, 'wb') as f:
                    f.write(img_bytes)

                generated_images.append(f'/generated/{filename}')

        elif 'image_url' in response.output_data:
            img_url = response.output_data['image_url']
            img_response = requests.get(img_url)
            img_bytes = img_response.content

            filename = f"{uuid.uuid4()}.png"
            filepath = os.path.join(app.config['GENERATED_FOLDER'], filename)

            with open(filepath, 'wb') as f:
                f.write(img_bytes)

            generated_images.append(f'/generated/{filename}')

        elif 'sample' in response.output_data:
            samples = response.output_data['sample']
            if not isinstance(samples, list):
                samples = [samples]

            for sample_data in samples:
                if isinstance(sample_data, str):
                    img_bytes = base64.b64decode(sample_data)
                else:
                    img_bytes = sample_data

                filename = f"{uuid.uuid4()}.png"
                filepath = os.path.join(app.config['GENERATED_FOLDER'], filename)

                with open(filepath, 'wb') as f:
                    f.write(img_bytes)

                generated_images.append(f'/generated/{filename}')

        else:
            return jsonify({'error': 'No image data returned from API'}), 500

        return jsonify({
            'success': True,
            'images': generated_images,
            'seed': seed,
            'parameters': {
                'prompt': prompt,
                'negative_prompt': negative_prompt,
                'width': width,
                'height': height,
                'steps': steps,
                'guidance': guidance,
                'aspect_ratio': aspect_ratio,
                'resolution': resolution,
                'num_images': num_images
            }
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/uploads/<filename>')
def serve_upload(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.route('/generated/<filename>')
def serve_generated(filename):
    return send_from_directory(app.config['GENERATED_FOLDER'], filename)

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({
        'status': 'ok',
        'timestamp': datetime.now().isoformat(),
        'api_configured': API_KEY != 'fly-'
    })

@app.route('/api/delete/<image_type>/<filename>', methods=['DELETE'])
def delete_image(image_type, filename):
    try:
        if image_type == 'upload':
            folder = app.config['UPLOAD_FOLDER']
        elif image_type == 'generated':
            folder = app.config['GENERATED_FOLDER']
        else:
            return jsonify({'error': 'Invalid image type'}), 400

        filepath = os.path.join(folder, filename)

        if os.path.exists(filepath):
            os.remove(filepath)
            return jsonify({'success': True})
        else:
            return jsonify({'error': 'File not found'}), 404

    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False, threaded=True)
